/** Zero-based indexes of the lines in `code` that contain any of the markers. Throws when a marker matches nothing. */
export function linesWith(code: string, ...markers: string[]): number[] {
  const lines = code.split("\n");
  for (const marker of markers) {
    if (!lines.some((line) => line.includes(marker))) throw new Error(`No line contains "${marker}"`);
  }
  return lines.flatMap((line, index) => (markers.some((marker) => line.includes(marker)) ? [index] : []));
}

/** The member whose first line contains `signature`, through its closing brace, dedented. */
export function member(code: string, signature: string): string {
  const lines = code.split("\n");
  const start = lines.findIndex((line) => line.includes(signature));
  if (start < 0) throw new Error(`No line contains "${signature}"`);
  const indent = lines[start].length - lines[start].trimStart().length;
  const end = lines.findIndex((line, index) => index > start && line === " ".repeat(indent) + "}");
  return lines
    .slice(start, end + 1)
    .map((line) => line.slice(indent))
    .join("\n");
}
